import{_ as i,o as l,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const A=JSON.parse('{"title":"Architecting Cloud Storage for AI Native Applications - Nathan Goulding, Vultr","description":"","frontmatter":{"title":"Architecting Cloud Storage for AI Native Applications - Nathan Goulding, Vultr","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["云存储","Ceph","AI应用","分布式存储","高性能计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Architecting_Cloud_Storage_for_AI_Native_Applications_-_Nathan_Goulding_Vultr.md","filePath":"posts/2025/Architecting_Cloud_Storage_for_AI_Native_Applications_-_Nathan_Goulding_Vultr.md","lastUpdated":1780459816000}'),e={name:"posts/2025/Architecting_Cloud_Storage_for_AI_Native_Applications_-_Nathan_Goulding_Vultr.md"};function n(a,t,_,s,p,u){return l(),o("div",null,[...t[0]||(t[0]=[r("<p>在本次会议中，Nathan Goulding，Vulture的高级副总裁，深入探讨了Vulture云架构与Ceph存储在AI应用中的应用。以下是会议的关键要点：</p><ol><li><p><strong>Vulture公司简介</strong>：Vulture是全球最大的独立云服务提供商，拥有超过22年的运营历史和遍布全球的32个数据中心，提供低延迟服务，覆盖全球90%的人口。</p></li><li><p><strong>云基础设施的演进</strong>：从传统的云基础设施到云原生部署，包括微服务、不可变基础设施和基础设施即代码，以及AI原生应用的兴起。</p></li><li><p><strong>Vulture的云架构</strong>：</p><ul><li><strong>云原生应用架构</strong>：支持裸金属、虚拟机、Kubernetes等多种部署方式，通过CI/CD管道部署应用和模型。</li><li><strong>AI原生应用架构</strong>：通过微调模型后部署到目标区域，支持低延迟推理和数据治理。</li></ul></li><li><p><strong>存储解决方案</strong>：</p><ul><li><strong>对象存储</strong>：提供S3兼容API，适合对象存储。</li><li><strong>块存储</strong>：支持HDD、SSD、NVMe，提供灵活的块存储解决方案。</li><li><strong>文件系统存储</strong>：基于Ceph（RADOS）实现，支持多实例同时读写，适合AI工作负载。</li><li><strong>Ceph集成</strong>：Vulture使用Ceph作为底层存储技术，已部署超过60PB的Ceph存储。</li></ul></li><li><p><strong>高性能存储与网络</strong>：与AMD合作，部署AMD MI 300X GPU集群，存储性能要求高达50GB/s每GPU，支持InfiniBand和RoCE网络，确保高带宽和低延迟的存储访问。</p></li><li><p><strong>未来展望与行动计划</strong>：</p><ul><li>继续优化存储架构，支持AI原生应用的快速发展。</li><li>提供更多高性能存储选项，满足AI训练和推理的严苛需求。</li><li>开放更多API和服务，简化用户对云基础设施的访问和使用。</li></ul></li></ol><p>本次会议强调了Ceph在AI原生应用中的重要性和Vulture在云存储领域的领先技术，通过高性能存储和网络解决方案，Vulture为AI训练和推理提供了强大的支持。</p>",3)])])}const c=i(e,[["render",n]]);export{A as __pageData,c as default};
